import { ref } from 'vue'
import MiniSearch from 'minisearch'
import { withBase } from 'vitepress'
import { useAuth } from './useAuth'

const searchIndex = ref(null)
const isLoaded = ref(false)

export function useSearch() {
    const { isAuthenticated } = useAuth()

    const initSearch = async () => {
        if (isLoaded.value) return

        try {
            // Fetch the search index generated by VitePress
            // Note: This path might vary depending on build config, but usually hidden in assets
            // For a more robust solution, we might need a custom build hook or assume localized index
            // IMPORTANT: VitePress chunks search index. This is a simplified fetcher.
            // Ideally, we tap into VitePress's existing search capabilities if exposed.
            // Since they aren't fully exposed, we might need to fetch a generated JSON if configured.

            // FALLBACK: For this demo, we will use a mock index or try to fetch content if available.
            // In a real generic implementation, we would want to generate a search.json

            // Let's assume we can fetch a generated index or we build one on the fly from page data if accessible.
            // For now, let's CREATE a simple index from the current page + visible nav for demonstration,
            // OR better, let's try to access the window.__VP_HASH_MAP__ if available to find pages?

            // REVISED APPROACH: We will fail gracefully if no index is found, but for the DEMO to work:
            // We will perform a "Live Indexing" of the sidebar links (since they are known).

            const miniSearch = new MiniSearch({
                fields: ['title', 'text'], // fields to index for full-text search
                storeFields: ['title', 'link', 'excerpt', 'secured'] // fields to return with search results
            })

            // Mock Data for Demo Purposes until we hook into build pipeline
            const mockDocs = [
                // Secured Page
                { id: 1, title: 'Fluxive Ecosystem', text: 'Overview of the Fluxive Machineforce Ecosystem.', link: '/guide/ecosystem', excerpt: 'Deep dive into the fxCore, fxAgent, and fxEdge components.', secured: true },

                // Public Pages
                { id: 2, title: 'Getting Started', text: 'How to install and run the Fluxive Library.', link: '/guide/getting-started', excerpt: 'Step-by-step guide to setting up your environment.' },
                { id: 3, title: 'Architecture', text: 'Understanding the distributed architecture.', link: '/guide/architecture', excerpt: 'Technical specifications of the Fluxive node system.' },
                { id: 4, title: 'Studio Overview', text: 'The User Integrated Development Environment.', link: '/studio/overview', excerpt: 'Build and configure your agents in the Studio.' },
                { id: 5, title: 'Persistence', text: 'Backend administration and data storage.', link: '/persistence/overview', excerpt: 'Managing long-term memory and database states.' }
            ]

            miniSearch.addAll(mockDocs)
            searchIndex.value = miniSearch
            isLoaded.value = true

        } catch (e) {
            console.error('Failed to initialize search', e)
        }
    }

    const search = (query) => {
        if (!searchIndex.value) return []

        // 1. Get Raw Results
        const results = searchIndex.value.search(query, {
            fuzzy: 0.2,
            prefix: true,
            boost: { title: 4 } // Boost title matches
        })

        // 2. Filter based on Auth State
        return results.filter(item => {
            if (item.secured && !isAuthenticated.value) {
                return false // Hide secured content if not logged in
            }
            return true
        })
    }

    return {
        initSearch,
        search,
        isLoaded
    }
}
